"""Wire ``on_tool_call`` / ``modify_tool_call`` for an LLM tool-call batch."""

from __future__ import annotations

from typing import List, NamedTuple, Optional

import structlog

from rasa.mantle.hooks.constants import POINT_TOOL_CALL
from rasa.mantle.hooks.exceptions import HookExecutionError, RetryModel
from rasa.mantle.hooks.payloads import ToolCallPayload
from rasa.mantle.hooks.registry import HookRegistry
from rasa.mantle.hooks.runner import run_modify, run_observers
from rasa.mantle.hooks.utils import hook_identity
from rasa.shared.providers.llm.llm_response import LLMToolCall

structlogger = structlog.get_logger()


class ToolCallPreflightResult(NamedTuple):
    """Outcome of preflighting ``modify_tool_call`` for a full LLM batch."""

    tool_calls: List[LLMToolCall]
    retry: Optional[RetryModel] = None


async def preflight_tool_calls(
    registry: HookRegistry,
    tool_calls: List[LLMToolCall],
) -> ToolCallPreflightResult:
    """Run observe/modify tool-call hooks for every call before any dispatch.

    Invokes ``on_tool_call`` / ``modify_tool_call`` once per call in the batch,
    sequentially in LLM batch order. Observers fire-and-forget per call.
    ``RetryModel`` from any invocation discards the entire batch (no tool has
    run yet). Unexpected modify crashes/timeouts are fail-closed and raise
    ``HookExecutionError`` without dispatching. Unsupported ``HookRejection``
    is discarded by the runner (original call kept).

    Confirmation, constraint gates, and ``_call_tool_func`` still run later
    inside ``SkillExecutor.dispatch_tool_call``. Confirmation resume,
    settable writes, and correction replay never reach this path.
    """
    if (
        not registry.observers(POINT_TOOL_CALL)
        and registry.modifier(POINT_TOOL_CALL) is None
    ):
        return ToolCallPreflightResult(tool_calls=list(tool_calls))

    try:
        sender_id, channel = hook_identity()
    except LookupError:
        # Live turns establish MessageTurnContext; missing context is misuse
        # (e.g. isolated unit tests). Keep the batch unmodified.
        structlogger.warning(
            "mantle.hooks.tool_call.skipped_no_turn_context",
        )
        return ToolCallPreflightResult(tool_calls=list(tool_calls))

    preflighted: List[LLMToolCall] = []

    for tc in tool_calls:
        payload = ToolCallPayload(
            sender_id=sender_id,
            channel=channel,
            tool_name=tc.tool_name,
            arguments=dict(tc.tool_args),
        )
        run_observers(registry, POINT_TOOL_CALL, payload)
        result = await run_modify(registry, POINT_TOOL_CALL, payload)

        if isinstance(result.control_flow, RetryModel):
            return ToolCallPreflightResult(
                tool_calls=list(tool_calls),
                retry=result.control_flow,
            )

        modified = result.payload
        if not isinstance(modified, ToolCallPayload):
            raise HookExecutionError(
                "modify_tool_call returned an unexpected payload type."
            )
        if not modified.tool_name:
            raise HookExecutionError("modify_tool_call returned an empty tool_name.")
        # Preserve engine-owned tool-call id and provider type; headers are
        # payload-only today (not plumbed into dispatch).
        preflighted.append(
            LLMToolCall(
                id=tc.id,
                tool_name=modified.tool_name,
                tool_args=dict(modified.arguments),
                type=tc.type,
            )
        )

    return ToolCallPreflightResult(tool_calls=preflighted)
